INSERT INTO lessons (course_id, title, content, lesson_type, sort_order, xp_reward, duration_minutes) VALUES
(@kurs_id, 'Co je Git', '<h2>Verzování a jeho smysl</h2><p>Verzování (version control) je systém, který ukládá historii změn v souborech. Umožňuje návrat k předchozím stavům, sledování kdo a kdy co změnil a paralelní práci více lidí. Bez verzování se projekt stává noční můrou — soubory jako <code>projekt_final_v2_OPRAVA.docx</code> jsou důkazem chaosu.</p><h2>Proč Git</h2><p>Git je nejrozšířenější verzovací systém na světě. Vytvořil ho Linus Torvalds v roce 2005 pro vývoj jádra Linuxu. Mezi jeho hlavní výhody patří:</p><ul><li><strong>Rychlost</strong> — většina operací probíhá lokálně bez přístupu k síti</li><li><strong>Distribuovanost</strong> — každý vývojář má kompletní kopii celého repozitáře včetně historie</li><li><strong>Integrita</strong> — každý objekt je identifikován SHA-1 hashem, nelze tajně měnit historii</li><li><strong>Větve</strong> — vytváření a slučování větví je extrémně rychlé a levné</li></ul><h2>Distribuovanost versus centralizované systémy</h2><p>Starší systémy jako SVN nebo CVS jsou centralizované — vyžadují připojení k serveru pro většinu operací. Git je distribuovaný: každý klon obsahuje celou historii. Pokud server spadne, můžeš pokračovat v práci a později synchronizovat.</p><pre><code># Ověření instalace Gitu\ngit --version\n# git version 2.47.0</code></pre><h2>Krátká historie</h2><p>Linus Torvalds používal proprietární BitKeeper pro vývoj Linuxu. Když byla odstraněna bezplatná licence, rozhodl se napsat vlastní nástroj. První verze Gitu vznikla během několika dní v dubnu 2005. Dnes Git používá přes 90 % vývojářů na světě.</p>', 'lesson', 1, 15, 12),

(@kurs_id, 'Instalace a konfigurace', '<h2>Instalace Gitu</h2><p>Na Windows stáhni instalátor z <code>git-scm.com</code>. Na macOS použij <code>brew install git</code> nebo Xcode Command Line Tools. Na Linuxu nainstaluj přes balíčkovací systém:</p><pre><code># Ubuntu/Debian\nsudo apt install git\n\n# Fedora\nsudo dnf install git\n\n# Arch\nsudo pacman -S git</code></pre><h2>Základní konfigurace</h2><p>Po instalaci je nutné nastavit jméno a e-mail — ty se objeví v každém commitu:</p><pre><code>git config --global user.name "Jan Novak"\ngit config --global user.email "jan@example.com"\n\n# Ověření nastavení\ngit config --list\n# user.name=Jan Novak\n# user.email=jan@example.com</code></pre><h2>SSH klíč pro GitHub</h2><p>SSH klíč umožňuje bezpečnou komunikaci s GitHubem bez hesla:</p><pre><code># Generování SSH klíče\nssh-keygen -t ed25519 -C "jan@example.com"\n\n# Spuštění SSH agenta\neval "$(ssh-agent -s)"\n\n# Přidání klíče do agenta\nssh-add ~/.ssh/id_ed25519\n\n# Zobrazení veřejného klíče (přidej na GitHub)\ncat ~/.ssh/id_ed25519.pub</code></pre><h2>Soubor .gitconfig</h2><p>Globální konfigurace je uložena v <code>~/.gitconfig</code>. Můžeš ji editovat ručně:</p><pre><code>[user]\n    name = Jan Novak\n    email = jan@example.com\n[core]\n    editor = code --wait\n    autocrlf = input\n[init]\n    defaultBranch = main\n[alias]\n    st = status\n    co = checkout\n    br = branch\n    ci = commit</code></pre>', 'lesson', 2, 15, 15),

(@kurs_id, 'První repozitář', '<h2>Vytvoření repozitáře</h2><p>Repozitář (repo) je adresář sledovaný Gitem. Obsahuje skrytou složku <code>.git</code> s celou historií. Vytvoříš ho dvěma způsoby:</p><pre><code># Zcela nový repozitář\nmkdir muj-projekt\ncd muj-projekt\ngit init\n# Initialized empty Git repository in /muj-projekt/.git/\n\n# Nebo klonování existujícího\ngit clone https://github.com/uzivatel/repo.git\ngit clone git@github.com:uzivatel/repo.git  # přes SSH</code></pre><h2>První commit</h2><p>Pracovní cyklus Gitu má tři fáze: pracovní adresář, staging area a repozitář. Soubory musíš nejprve přidat do staging area a pak commitnout:</p><pre><code># Vytvoření souboru\necho "# Muj projekt" > README.md\n\n# Zobrazení stavu\ngit status\n# Untracked files: README.md\n\n# Přidání do staging area\ngit add README.md\ngit add .            # přidá všechny změny\n\n# Vytvoření commitu\ngit commit -m "Pridani README"\n# [main (root-commit) a1b2c3d] Pridani README\n#  1 file changed, 1 insertion(+)</code></pre><h2>Soubor .gitignore</h2><p>Soubor <code>.gitignore</code> určuje, které soubory Git má ignorovat — například build artefakty, tajné klíče nebo závislosti:</p><pre><code># .gitignore\nnode_modules/\n.env\n*.log\ndist/\nbuild/\n.DS_Store\n__pycache__/\n*.pyc\n.vscode/\ncoverage/</code></pre><p>Každý řádek je vzor. <code>*</code> nahrazuje libovolné znaky, <code>!</code> vynuceně zahrne soubor, <code>/</code> na začátku omezuje na kořen repozitáře.</p>', 'lesson', 3, 15, 15),

(@kurs_id, 'Historie a logy', '<h2>Příkaz git log</h2><p>Příkaz <code>git log</code> zobrazuje historii commitů. Základní výpis je podrobný, ale existuje mnoho užitečných přepínačů:</p><pre><code># Základní výpis\ngit log\n\n# Kompaktní výpis — jeden commit na řádek\ngit log --oneline\n# a1b2c3d Pridani README\n# e4f5g6h Inicializace projektu\n\n# Grafické zobrazení větví\ngit log --oneline --graph --all\n# * a1b2c3d (HEAD -> main) Pridani README\n# * e4f5g6h Inicializace projektu\n\n# Posledních 5 commitů\ngit log -5\n\n# Log konkrétního souboru\ngit log -- app.js\n\n# Log s rozdílem (patch)\ngit log -p\n\n# Statistika změn\ngit log --stat</code></pre><h2>Příkaz git diff</h2><p><code>git diff</code> ukazuje rozdíly mezi různými stavy souborů:</p><pre><code># Rozdíl mezi pracovním adresářem a staging area\ngit diff\n\n# Rozdíl mezi staging area a posledním commitem\ngit diff --staged\n\n# Rozdíl mezi dvěma commity\ngit diff abc1234 def5678\n\n# Rozdíl mezi dvěma větvemi\ngit diff main..feature\n\n# Pouze názvy změněných souborů\ngit diff --name-only</code></pre><h2>Příkaz git show</h2><p><code>git show</code> zobrazí detail konkrétního commitu včetně změn:</p><pre><code># Poslední commit\ngit show\n\n# Konkrétní commit\ngit show a1b2c3d\n\n# Jen statistika\ngit show --stat a1b2c3d\n\n# Jen změny konkrétního souboru v commitu\ngit show a1b2c3d -- app.js</code></pre>', 'lesson', 4, 15, 15),

(@kurs_id, 'Větve (branches)', '<h2>Co jsou větve</h2><p>Větev (branch) je ukazatel na konkrétní commit. Vytváření větví v Gitu je extrémně rychlé — pouze se vytvoří nový ukazatel, nekopírují se soubory. Větve umožňují pracovat na funkcích paralelně bez ovlivnění hlavního kódu.</p><h2>Základní operace s větvemi</h2><pre><code># Seznam větví\ngit branch\n# * main\n\n# Vytvoření nové větve\ngit branch feature/login\n\n# Přepnutí na větev\ngit checkout feature/login\n# nebo novější příkaz:\ngit switch feature/login\n\n# Vytvoření a přepnutí najednou\ngit checkout -b feature/signup\ngit switch -c feature/signup\n\n# Smazání větve (po slučení)\ngit branch -d feature/login\n\n# Smazání nedsloučené větve (force)\ngit branch -D experiment\n\n# Přejmenování větve\ngit branch -m stary-nazev novy-nazev\n\n# Přejmenování aktuální větve\ngit branch -m novy-nazev</code></pre><h2>Kde se nacházím — HEAD</h2><p><code>HEAD</code> je speciální ukazatel na aktuálně aktivní větev (nebo commit). Příkaz <code>git log</code> vždy ukazuje, kam HEAD směřuje. Při přepnutí větve se HEAD přesune na tip nové větve.</p><h2>Práce ve větvi</h2><pre><code># Vytvoř větev pro novou funkci\ngit switch -c feature/header\n\n# Udělej změny a commitni\necho "&lt;header&gt;Moje stranka&lt;/header&gt;" > index.html\ngit add index.html\ngit commit -m "Pridani header komponenty"\n\n# Vrať se na main a slouč\ngit switch main\ngit merge feature/header\n\ngit branch -d feature/header</code></pre>', 'lesson', 5, 15, 15),

(@kurs_id, 'Slučování', '<h2>Příkaz git merge</h2><p>Slučování (merge) integruje změny z jedné větve do druhé. Před sloučením se vždy přepni na cílovou větev:</p><pre><code># Přepni na main\ngit switch main\n\n# Sluč feature do main\ngit merge feature/header\n# Updating a1b2c3d..e4f5g6h\n# Fast-forward\n#  index.html | 1 +\n#  1 file changed, 1 insertion(+)</code></pre><h2>Fast-forward merge</h2><p>Pokud se od větve feature neodštěpily žádné další commity v main, Git jednoduše přesune ukazatel main dopředu. Vznikne lineární historie bez merge commitu:</p><pre><code># Před sloučením:\n# main:    A --- B\n# feature:        \\--- C --- D\n#\n# Po fast-forward:\n# main:    A --- B --- C --- D</code></pre><h2>Třícestný merge (3-way merge)</h2><p>Pokud existují nové commity v obou větvích, Git vytvoří merge commit se dvěma rodiči:</p><pre><code># Před sloučením:\n# main:    A --- B --- E\n# feature:      \\--- C --- D\n#\n# Po 3-way merge:\n# main:    A --- B --- E --- M\n# feature:      \\--- C --- D --/\n# M je merge commit</code></pre><h2>Konflikty při slučování</h2><p>Konflikt vznikne, když se stejný řádek stejného souboru změnil v obou větvích. Git označí konflikt v souboru:</p><pre><code>&lt;&lt;&lt;&lt;&lt;&lt;&lt; HEAD\n&lt;h1&gt;Uvitani na strance&lt;/h1&gt;\n=======\n&lt;h1&gt;Vitejte na nasem webu&lt;/h1&gt;\n&gt;&gt;&gt;&gt;&gt;&gt;&gt; feature/header</code></pre><h2>Řešení konfliktů</h2><pre><code># 1. Otevři konfliktní soubor a uprav ho\n# 2. Odstraň značky &lt;&lt;&lt;&lt;&lt;&lt;&lt;, =======, &gt;&gt;&gt;&gt;&gt;&gt;&gt;\n# 3. Ponechat požadovanou verzi (nebo kombinaci obou)\n# 4. Přidej a commitni\ngit add index.html\ngit commit -m "Reseni konfliktu v header"\n\n# Pokud chceš zrušit sloučení\ngit merge --abort</code></pre><p>Tip: Před sloučením vždy proveď <code>git diff main...feature</code> a zkontroluj změny.</p>', 'lesson', 6, 15, 18),

(@kurs_id, 'Remoty', '<h2>Co jsou remoty</h2><p>Remote je odkaz na vzdálený repozitář (např. na GitHubu). Lokální repozitář může mít více remotů. Výchozí remote se jmenuje <code>origin</code>.</p><h2>Správa remotů</h2><pre><code># Seznam remotů\ngit remote\n# origin\n\n# Podrobné informace včetně URL\ngit remote -v\n# origin  https://github.com/uzivatel/repo.git (fetch)\n# origin  https://github.com/uzivatel/repo.git (push)\n\n# Přidání remote\ngit remote add origin https://github.com/uzivatel/repo.git\n\n# Přidání dalšího remote (např. upstream pro fork)\ngit remote add upstream https://github.com/puvodni/repo.git\n\n# Změna URL remote\ngit remote set-url origin git@github.com:uzivatel/repo.git\n\n# Smazání remote\ngit remote remove upstream\n\n# Přejmenování remote\ngit remote rename old-name new-name</code></pre><h2>git fetch</h2><p><code>git fetch</code> stáhne změny ze vzdáleného repozitáře, ale nemodifikuje pracovní adresář. Uloží je do remote-tracking větví (např. <code>origin/main</code>):</p><pre><code># Stažení všech remotů\ngit fetch\n\n# Stažení konkrétního remote\ngit fetch origin\n\n# Stažení konkrétní větve\ngit fetch origin feature/login\n\n# Zobrazení stažených změn\ngit log HEAD..origin/main</code></pre><h2>git pull</h2><p><code>git pull</code> je zkratka za <code>git fetch</code> + <code>git merge</code>. Stáhne a automaticky slučuje vzdálené změny do aktuální větve:</p><pre><code># Standardní pull\ngit pull origin main\n\n# Pull s rebase místo merge\ngit pull --rebase origin main\n\n# Pull všech větví\ngit pull --all</code></pre><h2>git push</h2><pre><code># Odeslání aktuální větve\ngit push origin main\n\n# První odeslání nové větve (-u nastaví tracking)\ngit push -u origin feature/login\n\n# Odeslání všech lokálních větví\ngit push --all\n\n# Smazání vzdálené větve\ngit push origin --delete feature/login\n\n# Force push (pozor — přepíše historii!)\ngit push --force-with-lease origin main</code></pre>', 'lesson', 7, 15, 18),

(@kurs_id, 'GitHub', '<h2>Co je GitHub</h2><p>GitHub je webová platforma pro hostování Git repozitářů a spolupráci. Nabízí Issues, Projects, Actions, Discussions a mnoho dalších funkcí. Pozor: GitHub není Git — Git je verzovací systém, GitHub je služba nad ním.</p><h2>Vytvoření repozitáře</h2><p>Na GitHubu klikni na <strong>New repository</strong>. Důležitá nastavení:</p><ul><li><strong>Public/Private</strong> — viditelnost repozitáře</li><li><strong>README</strong> — inicializace souborem README.md</li><li><strong>.gitignore</strong> — výběr šablony ignorovaných souborů</li><li><strong>License</strong> — MIT, Apache, GPL — určuje, jak mohou ostatní používat kód</li></ul><pre><code># Propojení lokálního repozitáře s GitHubem\ngit remote add origin https://github.com/uzivatel/muj-projekt.git\ngit branch -M main\ngit push -u origin main</code></pre><h2>Soubor README.md</h2><p>README je první soubor, který návštěvník repozitáře uvidí. Obsahuje popis projektu, instrukce k instalaci a použití:</p><pre><code># Muj Projekt\n\nPopis toho, co projekt dělá.\n\n## Instalace\n\n```bash\ngit clone https://github.com/uzivatel/muj-projekt.git\ncd muj-projekt\nnpm install\n```\n\n## Použití\n\n```bash\nnpm start\n```</code></pre><h2>Issues</h2><p>Issues slouží ke sledování chyb, nápadů a úkolů. Mohou obsahovat štítky (labels), přiřazené osoby (assignees), milníky (milestones) a komentáře.</p><h2>Projects</h2><p>GitHub Projects je kanbanová nástěnka pro organizaci práce. Sloupečky jako To Do, In Progress, Done. Propojení s Issues a Pull Requests pro automatický pohyb karet.</p>', 'lesson', 8, 15, 15),

(@kurs_id, 'Pull Requests', '<h2>Co je Pull Request</h2><p>Pull Request (PR) je žádost o slučování změn z jedné větve do druhé. Je to základní nástroj pro code review a spolupráci na GitHubu. Umožňuje diskuzi, kontrolu kódu a CI testy před samotným sloučením.</p><h2>Workflow: Fork a Pull Request</h2><pre><code># 1. Forkni repozitář na GitHubu (tlačítko Fork)\n\n# 2. Klonuj svůj fork\ngit clone https://github.com/tvuj-uzivatel/puvodni-repo.git\ncd puvodni-repo\n\n# 3. Přidej upstream remote\ngit remote add upstream https://github.com/puvodni/repo.git\n\n# 4. Vytvoř feature větev\ngit switch -c feature/nova-funkce\n\n# 5. Udělej změny a commitni\necho "Nova funkce" > feature.txt\ngit add feature.txt\ngit commit -m "Pridani nove funkce"\n\n# 6. Odešli do svého forku\ngit push -u origin feature/nova-funkce\n\n# 7. Na GitHubu vytvoř Pull Request z tvého forku do puvodni/repo</code></pre><h2>Code Review</h2><p>Code review je proces, kdy ostatní vývojáři kontrolují kód před sloučením. Na GitHubu mohou:</p><ul><li>Komentovat konkrétní řádky (inline comments)</li><li>Navrhnout změny (suggestions)</li><li>Schválit (approve) nebo požádat o úpravy (request changes)</li></ul><h2>Kontrolní seznam před merge</h2><pre><code># Aktualizace z upstream před mergem\ngit fetch upstream\ngit rebase upstream/main\n\n# Vyřešení konfliktů (pokud existují)\ngit add .\ngit rebase --continue\n\n# Force push po rebase\ngit push --force-with-lease origin feature/nova-funkce\n\n# Na GitHubu:\n# - Zkontroluj CI checky (zelené zaškrtnutí)\n# - Zkontroluj code review approvals\n# - Smaž větev po mergi (tlačítko Delete branch)</code></pre>', 'lesson', 9, 15, 18),

(@kurs_id, 'Tagy a releasy', '<h2>Co jsou tagy</h2><p>Tag je neměnný ukazatel na konkrétní commit, obvykle používaný pro označení verze (v1.0.0, v2.1.3). Na rozdíl od větví se tagy po nových commitech neposouvají.</p><h2>Typy tagů</h2><pre><code># Lightweight tag — jen ukazatel\ngit tag v1.0.0\n\n# Annotated tag — obsahuje zprávu, autora, datum\ngit tag -a v1.0.0 -m "Prvni stabilni verze"\n\n# Zobrazení všech tagů\ngit tag\n# v1.0.0\n# v1.1.0\n# v2.0.0\n\n# Tag na konkrétní commit\ngit tag -a v0.9.0 abc1234 -m "Beta verze"\n\n# Detail tagu\ngit show v1.0.0\n\n# Smazání tagu\ngit tag -d v1.0.0</code></pre><h2>Odeslání tagů na vzdálený repozitář</h2><pre><code># Odeslání konkrétního tagu\ngit push origin v1.0.0\n\n# Odeslání všech tagů\ngit push origin --tags\n\n# Smazání tagu na remote\ngit push origin --delete v1.0.0</code></pre><h2>Sémantické verzování (SemVer)</h2><p>Formát <code>MAJOR.MINOR.PATCH</code>:</p><ul><li><strong>MAJOR</strong> — nekompatibilní změny API</li><li><strong>MINOR</strong> — nová funkcionalita zpětně kompatibilní</li><li><strong>PATCH</strong> — opravy chyb zpětně kompatibilní</li></ul><h2>GitHub Releases</h2><p>Release na GitHubu je tag obohacený o poznámky k vydání a binární soubory. Vytvoříš ho v záložce Releases repozitáře. Může obsahovat:</p><ul><li>Changelog — seznam změn od předchozí verze</li><li>Přiložené soubory (assets) — binárky, balíčky</li><li>Označení jako pre-release pro betaverze</li></ul><pre><code># Vytvoření tagu pro release\ngit tag -a v2.0.0 -m "Velka aktualizace"\ngit push origin v2.0.0\n# Poté na GitHubu: Releases -> Draft a new release</code></pre>', 'lesson', 10, 15, 15),

(@kurs_id, 'Stash a cherry-pick', '<h2>git stash</h2><p><code>git stash</code> dočasně uloží necommitnuté změny (pracovní adresář i staging area) a vrátí repozitář do čistého stavu. Ideální, když potřebuješ rychle přepnout větev:</p><pre><code># Uložení změn do stash\ngit stash\n# Saved working directory and index state WIP on feature: abc1234\n\n# S popisem\ngit stash push -m "Prace na header komponente"\n\n# Seznam stash zásobníků\ngit stash list\n# stash@{0}: On feature: Prace na header komponente\n# stash@{1}: WIP on main: def5678 Fix bug\n\n# Obnovení posledního stash (a ponechání v seznamu)\ngit stash apply\n\n# Obnovení konkrétního stash\ngit stash apply stash@{1}\n\n# Obnovení a smazání ze seznamu\ngit stash pop\n\n# Smazání stash\ngit stash drop stash@{0}\n\n# Smazání všech stash\ngit stash clear\n\n# Zobrazení obsahu stash\ngit stash show -p stash@{0}</code></pre><h2>git cherry-pick</h2><p><code>git cherry-pick</code> aplikuje změny z konkrétního commitu do aktuální větve. Užitečné, když potřebuješ přenést konkrétní opravu bez slučování celé větve:</p><pre><code># Aplikování jednoho commitu\ngit cherry-pick abc1234\n\n# Aplikování rozsahu commitů\ngit cherry-pick abc1234..def5678\n\n# Pouze vytvoření změn bez commitu (--no-commit)\ngit cherry-pick --no-commit abc1234\n\n# Při konfliktu\ngit cherry-pick --continue   # po vyřešení\ngit cherry-pick --abort       # zrušení</code></pre><h2>Kdy použít stash a kdy cherry-pick</h2><ul><li><strong>Stash</strong> — dočasné uložení rozpracované práce, potřebuješ přepnout větev</li><li><strong>Cherry-pick</strong> — přenesení konkrétního commitu (např. hotfix) do jiné větve</li></ul>', 'lesson', 11, 15, 15),

(@kurs_id, 'Rebase', '<h2>Co je rebase</h2><p><code>git rebase</code> přesklládá commity tak, že vezme commity z aktuální větve a "přehraje" je na konec cílové větve. Výsledkem je lineární historie bez merge commitů:</p><pre><code># Před rebase:\n# main:    A --- B --- C\n# feature:      \\--- D --- E\n#\n# git rebase main (na větvi feature)\n# Po rebase:\n# main:    A --- B --- C\n# feature:            \\--- D'' --- E''</code></pre><h2>Základní použití</h2><pre><code># Přehrání feature na main\ngit switch feature\ngit rebase main\n\n# Při konfliktu\ngit rebase --continue   # po vyřešení\ngit rebase --abort     # zrušení celého rebase</code></pre><h2>Interaktivní rebase</h2><p>Interaktivní rebase umožňuje upravit historii — squash, reword, edit, reorder commitů:</p><pre><code># Uprav posledních 5 commitů\ngit rebase -i HEAD~5\n\n# Otevře editor s seznamem:\n# pick abc1234 Pridani README\n# pick def5678 Novy styl\n# squash ghi9012 Oprava preklepu   # squash sloučí s předchozím\n# reword jkl3456 Zmena configu     # reword změní zprávu\n# edit mno7890 Refaktoring         # edit zastaví pro úpravu commitu\n#\n# Možnosti:\n# pick    — ponechat beze změny\n# reword  — změnit zprávu commitu\n# edit    — zastavit pro úpravu commitu\n# squash  — sloučit s předchozím commitem\n# drop    — smazat commit\n# reorder — změnit pořadí (přesunutím řádků)</code></pre><h2>Kdy NEPOUŽÍVAT rebase</h2><p>Zlaté pravidlo: <strong>Nikdy nerebaset veřejné větve, na kterých pracují ostatní!</strong> Rebase přepisuje historii — commity dostanou nové hashe. Pokud někdo už staré commity stáhl, vznikne chaos s konflikty.</p><pre><code># SPRÁVNĚ: rebase vlastní feature větev na main\ngit switch feature/my-work\ngit rebase main\n\n# ŠPATNĚ: rebase main na feature (přepíše historii main!)\ngit switch main\ngit rebase feature  # NIKDY!</code></pre>', 'lesson', 12, 15, 18),

(@kurs_id, 'Reset a revert', '<h2>git reset</h2><p><code>git reset</code> přesune ukazatel HEAD na jiný commit. Má tři režimy podle toho, co se stane se změnami:</p><pre><code># --soft: zachová změny v staging area\ngit reset --soft HEAD~1\n# HEAD se posune o 1 commit zpět\n# Změny z commitu zůstanou staged\n\n# --mixed (výchozí): zachová změny v pracovním adresáři\ngit reset HEAD~1\n# nebo\ngit reset --mixed HEAD~1\n# Změny z commitu zůstanou v pracovním adresáři (unstaged)\n\n# --hard: zahodí VŠECHNY změny\ngit reset --hard HEAD~1\n# POZOR: Změny z commitu budou navždy ztraceny!\n\n# Reset na konkrétní commit\ngit reset --soft abc1234</code></pre><h2>Praktické příklady</h2><pre><code># Odcommitni poslední commit, ale zachovej změny\ngit reset --soft HEAD~1\n# Nyní můžeš upravit a commitnout znovu\ngit commit -m "Lepsi popis zmeny"\n\n# Unstage všechno (praktické při špatném git add)\ngit reset HEAD\n\n# Zahodit všechny lokální změny a vrátit se k poslednímu commitu\ngit reset --hard HEAD\n\n# Zahodit změny v konkrétním souboru\ngit checkout -- app.js\n# nebo nověji:\ngit restore app.js</code></pre><h2>git revert</h2><p><code>git revert</code> vytvoří nový commit, který invertuje změny zadaného commitu. Na rozdíl od reset nezmění historii — je bezpečný pro sdílené větve:</p><pre><code># Vrácení posledního commitu\ngit revert HEAD\n# Otevře editor pro zprávu revert commitu\n\n# Vrácení konkrétního commitu\ngit revert abc1234\n\n# Vrácení bez editace zprávy\ngit revert --no-edit abc1234\n\n# Vrácení rozsahu commitů\ngit revert abc1234..def5678\n\n# Vrácení bez automatického commitu (můžeš upravit)\ngit revert --no-commit abc1234\ngit commit -m "Vraceni zmeny s upravou"</code></pre><h2>Reset vs. Revert — kdy co použít</h2><ul><li><strong>reset</strong> — lokální změny, ještě nepushnuté commity, osobní větve</li><li><strong>revert</strong> — sdílené větve, commity už pushnuté na remote</li></ul>', 'lesson', 13, 15, 18),

(@kurs_id, 'Git hooks', '<h2>Co jsou Git hooks</h2><p>Git hooks jsou skripty, které se automaticky spouštějí při určitých událostech v repozitáři — před commitnutím, před pushnutím, po přijetí commitu atd. Skripty jsou uloženy v <code>.git/hooks/</code>.</p><h2>Typy hooks</h2><pre><code># Client-side hooks (spouští se lokálně):\n# pre-commit      — před vytvořením commitu (ideální pro lint)\n# prepare-commit-msg — před editací zprávy commitu\n# commit-msg      — po zadání zprávy commitu\n# post-commit     — po vytvoření commitu\n# pre-push        — před odesláním na remote\n\n# Server-side hooks (spouští se na serveru):\n# pre-receive     — před přijetím pushnutých commitů\n# update         — pro každou pushnutou větev\n# post-receive   — po přijetí pushnutých commitů</code></pre><h2>Příklad: pre-commit hook</h2><pre><code># .git/hooks/pre-commit (musí být spustitelný: chmod +x)\n#!/bin/sh\n\n# Spustit lint před commitem\nnpm run lint\nif [ $? -ne 0 ]; then\n    echo "Lint selhal! Oprav chyby pred commitnutim."\n    exit 1\nfi\n\n# Zabránit commitnutí souborů větších než 1MB\nmax_size=1048576\nlarge_files=$(git diff --cached --name-only | \\\n    xargs -I {} find {} -size +${max_size}c 2>/dev/null)\n\nif [ -n "$large_files" ]; then\n    echo "Velke soubory detekovany: $large_files"\n    exit 1\nfi</code></pre><h2>Husky — správa hooks v Node.js projektech</h2><p>Husky zjednodušuje správu Git hooks — definuješ je v <code>package.json</code> místo skriptů v <code>.git/hooks/</code>:</p><pre><code># Instalace\nnpm install --save-dev husky\n\n# Inicializace\nnpx husky init\n\n# Vytvoření pre-commit hook\necho "npm run lint" > .husky/pre-commit\n\n# Vytvoření commit-msg hook pro Conventional Commits\necho "npx --no -- commitlint --edit \$1" > .husky/commit-msg</code></pre><h2>lint-staged</h2><p>lint-staged spouští lint pouze na souborech ve staging area — mnohem rychlejší než lint celého projektu:</p><pre><code># package.json\n{\n  "lint-staged": {\n    "*.js": "eslint --fix",\n    "*.css": "stylelint --fix",\n    "*.{js,css,md}": "prettier --write"\n  }\n}\n\n# Spojení s husky\necho "npx lint-staged" > .husky/pre-commit</code></pre>', 'lesson', 14, 15, 18),

(@kurs_id, 'CI/CD s GitHub Actions', '<h2>Co je CI/CD</h2><p>CI (Continuous Integration) automaticky spouští testy při každém pushnutí nebo PR. CD (Continuous Deployment) automaticky nasazuje aplikaci po úspěšných testech. GitHub Actions je vestavěný CI/CD systém na GitHubu.</p><h2>Struktura workflow</h2><p>Workflows jsou YAML soubory v adresáři <code>.github/workflows/</code>:</p><pre><code># .github/workflows/ci.yml\nname: CI\n\non:\n  push:\n    branches: [main]\n  pull_request:\n    branches: [main]\n\njobs:\n  test:\n    runs-on: ubuntu-latest\n\n    strategy:\n      matrix:\n        node-version: [18.x, 20.x]\n\n    steps:\n      - uses: actions/checkout@v4\n\n      - name: Nastaveni Node.js ${{ matrix.node-version }}\n        uses: actions/setup-node@v4\n        with:\n          node-version: ${{ matrix.node-version }}\n\n      - name: Instalace zavislosti\n        run: npm ci\n\n      - name: Lint\n        run: npm run lint\n\n      - name: Testy\n        run: npm test\n\n      - name: Build\n        run: npm run build</code></pre><h2>Deploy workflow</h2><pre><code># .github/workflows/deploy.yml\nname: Deploy\n\non:\n  push:\n    branches: [main]\n\njobs:\n  deploy:\n    runs-on: ubuntu-latest\n    needs: []\n    steps:\n      - uses: actions/checkout@v4\n\n      - name: Build\n        run: npm run build\n\n      - name: Deploy na GitHub Pages\n        uses: peaceiris/actions-gh-pages@v3\n        with:\n          github_token: ${{ secrets.GITHUB_TOKEN }}\n          publish_dir: ./dist</code></pre><h2>Klíčové koncepty</h2><ul><li><strong>on</strong> — spouštěče (push, pull_request, schedule, workflow_dispatch)</li><li><strong>jobs</strong> — skupiny kroků, běží paralelně (nebo s <code>needs</code> sekvenčně)</li><li><strong>steps</strong> — jednotlivé příkazy nebo akce</li><li><strong>secrets</strong> — šifrované proměnné (API klíče, tokeny)</li><li><strong>matrix</strong> — testování na více verzích paralelně</li><li><strong>artifacts</strong> — dočasná data sdílená mezi jobs</li></ul>', 'lesson', 15, 15, 18),

(@kurs_id, 'Monorepo a submoduly', '<h2>Monorepo vs. Polyrepo</h2><p><strong>Monorepo</strong> — jeden repozitář obsahuje více souvisejících projektů (např. frontend, backend, shared libs). <strong>Polyrepo</strong> — každý projekt má vlastní repozitář. Monorepo usnadňuje sdílení kódu a konzistentní verzování, polyrepo dává týmům nezávislost.</p><h2>git submodule</h2><p>Submodul je odkaz na konkrétní commit v jiném repozitáři. Umožňuje vložit cizí repo do podadresáře:</p><pre><code># Přidání submodulu\ngit submodule add https://github.com/org/shared-libs.git libs/shared\n\n# Klonování repozitáře se submoduly\ngit clone --recurse-submodules https://github.com/org/monorepo.git\n\n# Nebo dodatečné stažení submodulů\ngit submodule update --init --recursive\n\n# Aktualizace submodulu na nejnovější commit\ngit submodule update --remote libs/shared\n\n# Smazání submodulu\ngit submodule deinit -f libs/shared\nrm -rf .git/modules/libs/shared\ngit rm libs/shared</code></pre><h2>git subtree</h2><p>Subtree je alternativa k submodulům — cizí repozitář se zkopíruje přímo do podadresáře (jako běžné soubory). Výhoda: ostatní vývojáři nemusí vědět o subtree:</p><pre><code># Přidání subtree\ngit subtree add --prefix=libs/shared \\\n    https://github.com/org/shared-libs.git main --squash\n\n# Aktualizace subtree\ngit subtree pull --prefix=libs/shared \\\n    https://github.com/org/shared-libs.git main --squash\n\n# Push změn zpět do subtree zdroje\ngit subtree push --prefix=libs/shared \\\n    https://github.com/org/shared-libs.git main</code></pre><h2>Monorepo strategie</h2><pre><code># Typická struktura monorepa\nmy-monorepo/\n  packages/\n    ui/         # frontend komponenty\n    api/        # backend API\n    shared/     # sdílené typy a utility\n  apps/\n    web/        # webová aplikace\n    mobile/     # mobilní aplikace\n  package.json  # root workspace\n  turbo.json    # Turborepo konfigurace</code></pre><p>Nástroje pro monorepo správu: <strong>pnpm workspaces</strong>, <strong>Turborepo</strong>, <strong>Nx</strong>, <strong>Lerna</strong>.</p>', 'lesson', 16, 15, 15),

(@kurs_id, 'Git ve týmu', '<h2>GitFlow</h2><p>GitFlow je model větvení s pevně definovanými rolemi větví. Vhodný pro projekty s pravidelnými releasy:</p><pre><code># Větve v GitFlow:\n# main      — produkční kód, pouze merge a tagy\n# develop   — vývojová větev, integruje všechny funkce\n# feature/* — nové funkce (odštěpuje se od develop)\n# release/* — příprava releasu (odštěpuje se od develop)\n# hotfix/*  — nouzové opravy (odštěpuje se od main)\n\n# Příklad workflow:\ngit switch -c feature/login develop\n# ... práce na funkci ...\ngit switch develop\ngit merge --no-ff feature/login\n\n# Příprava releasu\ngit switch -c release/1.2.0 develop\n# ... opravy, verze, dokumentace ...\ngit switch main\ngit merge --no-ff release/1.2.0\ngit tag -a v1.2.0\n\ngit switch develop\ngit merge --no-ff release/1.2.0</code></pre><h2>Trunk Based Development</h2><p>Jednodušší model — všichni commitují do jediné větve (main/trunk). Krátkodobé feature větve (max. 1-2 dny), časté integrace. Vhodný pro týmy s automatizovaným CI/CD:</p><pre><code># Trunk Based:\n# main — aktivní vývoj\n# feature/* — krátkodobé větve (< 1 den)\n#\n# Pravidla:\n# - Časté commity do main (min. 1x denně)\n# - Feature flags místo dlouhých větví\n# - Automatizované testování\n# - Pull request pro code review</code></pre><h2>Konvence commitů — Conventional Commits</h2><p>Standardizovaný formát zpráv commitů umožňuje automatické generování changelogů a verzování:</p><pre><code># Formát:\n# typ(obor): popis\n#\n# Typy:\n# feat     — nová funkce\n# fix      — oprava chyby\n# docs     — dokumentace\n# style    — formátování\n# refactor — refaktoring\n# test     — testy\n# chore    — údržba, závislosti\n# ci       — CI/CD změny\n\n# Příklady:\ngit commit -m "feat(auth): pridani prihlaseni pres Google"\ngit commit -m "fix(api): oprava timeout pri velkych datech"\ngit commit -m "docs: aktualizace instalacniho navodu"\ngit commit -m "chore(deps): upgrade na Node.js 20"</code></pre>', 'lesson', 17, 15, 18),

(@kurs_id, 'Pokročilé triky', '<h2>git bisect</h2><p><code>git bisect</code> provede binární vyhledávání v historii commitů, aby našel commit, který zavedl chybu. Označuješ commity jako "dobré" nebo "špatné" a Git úplně vyfiltruje problematický commit:</p><pre><code># Spuštění bisect\ngit bisect start\n\n# Aktuální commit je špatný (má chybu)\ngit bisect bad\n\n# Zadaný commit je dobrý (chybu nemá)\ngit bisect good v1.0.0\n# Bisect automaticky checkoutne commit uprostřed\n\n# Opakuj:\ngit bisect good   # pokud je aktuální commit v pořádku\ngit bisect bad    # pokud aktuální commit obsahuje chybu\n# ... opakuj, až Git najde viníka:\n# abc1234 is the first bad commit\n\n# Ukončení\ngit bisect reset\n\n# Automatický bisect se skriptem\ngit bisect run npm test</code></pre><h2>git reflog</h2><p><code>git reflog</code> sleduje všechny pohyby ukazatele HEAD. Je to bezpečnostní síť — i po <code>git reset --hard</code> nebo smazané větvi můžeš najít ztracené commity:</p><pre><code># Zobrazení reflogu\ngit reflog\n# a1b2c3d HEAD@{0}: commit: Nova funkce\n# def5678 HEAD@{1}: checkout: moving from feature to main\n# ghi9012 HEAD@{2}: commit: Prace na feature\n\n# Návrat ke ztracenému commitu\ngit checkout ghi9012\n# Nebo reset\ngit reset --hard ghi9012\n\n# Reflog pro konkrétní větev\ngit reflog show main\n\n# Pozor: reflog záznamy expirují (defaultně 90 dní)</code></pre><h2>git blame</h2><p><code>git blame</code> ukáže, kdo napsal každý řádek souboru a v jakém commitu:</p><pre><code># Základní použití\ngit blame app.js\n\n# Jen konkrétní řádky\ngit blame -L 10,30 app.js\n\n# Ignorovat přesuny řádků\ngit blame -M app.js\n\n# Sledovat přesuny z jiných souborů\ngit blame -C -C app.js</code></pre><h2>git grep</h2><pre><code># Hledání v repozitáři\ngit grep "TODO"\n\n# Hledání v konkrétních souborech\ngit grep "function" -- "*.js"\n\n# Počet výskytů na soubor\ngit grep --count "import"\n\n# Hledání v konkrétní větvi\ngit grep "deprecated" main\n\n# Zobrazení čísel řádků\ngit grep -n "className" -- "*.tsx"</code></pre>', 'lesson', 18, 15, 18),

(@kurs_id, 'VeVit projekt', '<h2>Kompletní workflow: přispívání do vevit-edu</h2><p>V této lekci projdeš kompletní workflow přispívání do reálného projektu vevit-edu na GitHubu. Od forku až po merge — přesně tak, jak to dělají profesionální vývojáři.</p><h2>Krok 1: Fork repozitáře vevit-edu</h2><p>Navštiv <code>github.com/vevit-edu/vevit-edu</code> a klikni na tlačítko <strong>Fork</strong> v pravém horním rohu. Tím vytvoříš kopii repozitáře pod svým účtem:</p><pre><code># Klonuj svůj fork\ngit clone https://github.com/TVUJ-UZIVATEL/vevit-edu.git\ncd vevit-edu\n\n# Přidej upstream remote (původní repozitář)\ngit remote add upstream https://github.com/vevit-edu/vevit-edu.git\n\n# Ověř remotes\ngit remote -v\n# origin    https://github.com/TVUJ-UZIVATEL/vevit-edu.git (fetch)\n# origin    https://github.com/TVUJ-UZIVATEL/vevit-edu.git (push)\n# upstream  https://github.com/vevit-edu/vevit-edu.git (fetch)\n# upstream  https://github.com/vevit-edu/vevit-edu.git (push)</code></pre><h2>Krok 2: Vytvoření feature větve</h2><pre><code># Ujisti se, že jsi na main a máš poslední změny\ngit switch main\ngit fetch upstream\ngit rebase upstream/main\n\n# Vytvoř feature větev s popisným názvem\ngit switch -c feature/add-rust-course\n\n# Název větve podle Conventional Commits:\n# feature/  — nová funkce\n# fix/      — oprava chyby\n# docs/     — dokumentace\n# chore/    — údržba</code></pre><h2>Krok 3: Provedení změn</h2><pre><code># Vytvoř SQL soubor pro nový kurz v adresáři database/\n# Například: database/14_rust_course.sql\n\n# Přidej soubory do staging area\ngit add database/14_rust_course.sql\n\n# Zkontroluj, co je staged\ngit status\ngit diff --staged\n\n# Vytvoř commit podle Conventional Commits\ngit commit -m "feat(course): pridani Rust kurzu"\n\n# Pokud děláš více commitů, squaschni je před PR\ngit rebase -i HEAD~3\n# Změň pick na squash u druhého a třetího commitu</code></pre><h2>Krok 4: Spuštění CI lokálně</h2><pre><code># Před pushnutím ověř, že CI projde\n# Zkontroluj syntaxi SQL souboru\nmysql -u root -p vevit_edu < database/14_rust_course.sql\n\n# Pokud projekt má linting\nnpm run lint\n\n# Pokud projekt má testy\nnpm test\n\n# Push do svého forku\ngit push -u origin feature/add-rust-course</code></pre><h2>Krok 5: Vytvoření Pull Request</h2><pre><code># Na GitHubu:\n# 1. Jdi na github.com/vevit-edu/vevit-edu\n# 2. Klikni "Compare & pull request"\n# 3. Zvol base: main <- compare: feature/add-rust-course\n# 4. Vyplň šablonu PR:\n#\n#    ## Popis\n#    Pridan kompletni Rust kurz (20 lekcí + kvíz)\n#\n#    ## Typ změny\n#    - [x] Nová funkce (feat)\n#\n#    ## Kontrolní seznam\n#    - [x] SQL syntaxe ověřena\n#    - [x] Všechny lekce mají obsah\n#    - [x] Kvíz obsahuje 10 otázek\n#    - [x] UPDATE courses na konci souboru\n#\n# 5. Odeslat PR</code></pre><h2>Krok 6: Code review a merge</h2><pre><code># Po code review možná dostaneš poznámky:\n# — Uprav soubor podle zpětné vazby\n# — Commitni a pushni\ngit add database/14_rust_course.sql\ngit commit -m "fix(course): opravy z code review"\ngit push origin feature/add-rust-course\n\n# Po schválení PR se sloučí (merge) do main\n# GitHub nabídne smazání větve — souhlasíš\n\n# Lokálně aktualizuj svůj fork\ngit switch main\ngit fetch upstream\ngit rebase upstream/main\ngit push origin main\n\n# Smaž lokální feature větev\ngit branch -d feature/add-rust-course</code></pre>', 'lesson', 19, 15, 20),

(@kurs_id, 'Shrnutí', '<h2>Co ses naučil</h2><p>Gratulujeme! Prošel jsi kompletní kurz Git a GitHub. Zde je rekapitulace klíčových témat:</p><ul><li><strong>Základy</strong> — Git init, add, commit, log, diff</li><li><strong>Větve</strong> — branch, switch, merge, řešení konfliktů</li><li><strong>Vzdálené repozitáře</strong> — remote, fetch, pull, push, clone</li><li><strong>GitHub</strong> — repozitář, README, Issues, Projects, Pull Requests</li><li><strong>Pokročilé techniky</strong> — rebase, stash, cherry-pick, reset, revert</li><li><strong>Automatizace</strong> — hooks, Husky, CI/CD s GitHub Actions</li><li><strong>Týmová spolupráce</strong> — GitFlow, Trunk Based, Conventional Commits</li><li><strong>Diagnostika</strong> — bisect, reflog, blame, grep</li></ul><h2>Kam dál</h2><ul><li><strong>GitHub Copilot</strong> — AI asistence při psaní kódu přímo v editoru</li><li><strong>GitHub Codespaces</strong> — vývojové prostředí v cloudu</li><li><strong>Pokročilý CI/CD</strong> — Docker, Kubernetes, Terraform</li><li><strong>Monorepo nástroje</strong> — Nx, Turborepo, pnpm workspaces</li><li><strong>Git internals</strong> — porozumění objektovému modelu Gitu</li></ul><h2>Zdroje</h2><ul><li><strong>Oficiální dokumentace</strong> — <code>git-scm.com/doc</code></li><li><strong>Pro Git kniha</strong> — <code>git-scm.com/book</code> (volně dostupná)</li><li><strong>GitHub Docs</strong> — <code>docs.github.com</code></li><li><strong>Conventional Commits</strong> — <code>conventionalcommits.org</code></li><li><strong>Oh Shit, Git!?!</strong> — <code>ohshitgit.com</code> (rychlé opravy chyb)</li></ul><h2>Cheat sheet</h2><pre><code># Základy\ngit init                    # nový repozitář\ngit clone &lt;url&gt;             # klonování\ngit status                  # stav souborů\ngit add .                   # přidání do staging\ngit commit -m "zprava"      # vytvoření commitu\n\n# Větve\ngit branch                  # seznam větví\ngit switch -c feature/x     # nová větev\ngit merge feature/x         # sloučení\ngit branch -d feature/x     # smazání větve\n\n# Vzdálené\ngit remote -v               # seznam remotů\ngit fetch origin             # stažení změn\ngit pull origin main        # stažení + sloučení\ngit push origin main        # odeslání změn\n\n# Historie\ngit log --oneline --graph  # vizualizace\ngit diff                   # rozdíly\ngit show abc1234            # detail commitu\n\n# Opravy\ngit stash                  # dočasné uložení\ngit reset --soft HEAD~1    # odcommitnutí\ngit revert abc1234          # vrácení commitu\ngit reflog                 # bezpečnostní síť\n\n# Tagy\ngit tag -a v1.0 -m "verze" # vytvoření tagu\ngit push origin --tags     # odeslání tagů</code></pre>', 'lesson', 20, 15, 15);

