INSERT INTO lessons (course_id, title, content, lesson_type, sort_order, xp_reward, duration_minutes) VALUES
(@kurs_id, 'Závěrečný kvíz — Git & GitHub', '<p>Závěrečný test pokrývající celý kurz Git a GitHub — od základů po pokročilé techniky.</p>', 'final_quiz', 21, 200, 25);

SET @qfin = LAST_INSERT_ID();

INSERT INTO quizzes (lesson_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, sort_order) VALUES
(@qfin, 'Co dělá příkaz git init?', 'Klonuje vzdálený repozitář', 'Vytvoří nový lokální repozitář', 'Smaže existující repozitář', 'Přidá remote origin', 'b', 'git init vytvoří nový prázdný repozitář v aktuálním adresáři (složka .git).', 1),
(@qfin, 'Jaký je rozdíl mezi git fetch a git pull?', 'fetch stahuje a slučuje, pull jen stahuje', 'fetch jen stahuje, pull stahuje a slučuje', 'Nejsou žádné rozdíly', 'fetch je pro SSH, pull pro HTTPS', 'b', 'git fetch stáhne změny do remote-tracking větví bez modifikace pracovního adresáře. git pull navíc provede merge.', 2),
(@qfin, 'Co je Fast-forward merge?', 'Merge, který vytvoří nový merge commit', 'Merge, kdy se ukazatel cílové větve posune dopředu bez merge commitu', 'Merge s konflikty', 'Merge, který smaže zdrojovou větev', 'b', 'Fast-forward merge nastane, když cílová větev nemá nové commity — ukazatel se prostě posune na tip zdrojové větve.', 3),
(@qfin, 'Jak označíš verzi v1.0.0 pomocí annotated tagu?', 'git tag v1.0.0', 'git tag -a v1.0.0 -m "Prvni verze"', 'git release v1.0.0', 'git version v1.0.0', 'b', 'Přepínač -a vytvoří annotated tag se zprávou, autorem a datem. Lightweight tag bez -a je jen ukazatel.', 4),
(@qfin, 'Kdy bys použil git revert místo git reset?', 'Když chceš smazat commity z historie', 'Když jsou commity už pushnuté na sdíleném remote', 'Když chceš zachovat lokální změny', 'Když nechceš vytvořit nový commit', 'b', 'git revert vytvoří nový commit, který invertuje změny — je bezpečný pro sdílené větve, protože nemění historii.', 5),
(@qfin, 'Co dělá git stash?', 'Smaže necommitnuté změny', 'Dočasně uloží necommitnuté změny a vrátí repozitář do čistého stavu', 'Vytvoří novou větev ze změn', 'Zobrazí seznam commitů', 'b', 'git stash uloží rozpracované změny do zásobníku a vrátí pracovní adresář do stavu posledního commitu.', 6),
(@qfin, 'Jaký je hlavní princip Conventional Commits?', 'Každý commit musí obsahovat číslo issue', 'Commit zpráva má formát typ(obor): popis', 'Všechny commity musí být squaschnuty', 'Commit zpráva musí být v angličtině', 'b', 'Conventional Commits definuje formát jako feat(auth): přidání přihlášení — typ určuje druh změny, obor je volitelný kontext.', 7),
(@qfin, 'Co je git bisect?', 'Vyhledá commit, který zavedl chybu, pomocí binárního vyhledávání', 'Rozdělí commit na menší části', 'Zobrazí rozdíl mezi dvěma větvemi', 'Automaticky řeší konflikty', 'a', 'git bisect provede binární vyhledávání v historii — označuješ commity jako good/bad a Git najde první špatný commit.', 8),
(@qfin, 'Co je GitHub Actions workflow?', 'Aplikace pro správu větví', 'YAML soubor v .github/workflows/ definující CI/CD pipeline', 'Druh Pull Requestu', 'Nástroj pro správu submodulů', 'b', 'GitHub Actions workflow je YAML soubor v .github/workflows/ definující jobs, steps a spouštěče pro automatizaci.', 9),
(@qfin, 'Při přispívání do vevit-edu repozitáře jaký je správný postup?', 'Clone main, commit přímo, push do main', 'Fork, vytvoř feature větev, commit, push do forku, vytvoř PR', 'Fork, commit přímo do main ve forku, push', 'Stáhni ZIP, uprav, pošli e-mailem', 'b', 'Správný workflow: fork repozitáře, vytvoření feature větve, commit a push do forku, vytvoření Pull Request do původního repozitáře.', 10);

